import { Center, Spinner, Text, VStack } from '@chakra-ui/react'

const Loading = () => {
    return (
        <Center h="100vh">
            <VStack>
                <Spinner thickness='4px' speed='0.65s' emptyColor='gray.200' color='blue.500' size='xl'/>
                <Text>Loading...</Text>
            </VStack>
            
            </Center>
            );
}



export default Loading;
